import{Z as t,e as o,f as a,a0 as n}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"Question","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/captchas/question.md","filePath":"integrations/captchas/question.md","lastUpdated":1781527112000}'),i={name:"integrations/captchas/question.md"};function s(r,e,l,c,h,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="question" tabindex="-1">Question <a class="header-anchor" href="#question" aria-label="Permalink to &quot;Question&quot;">​</a></h1><p>Follow the below steps to set up Formie&#39;s built-in Question captcha.</p><h3 id="step-1-open-the-captcha-settings" tabindex="-1">Step 1. Open the Captcha Settings <a class="header-anchor" href="#step-1-open-the-captcha-settings" aria-label="Permalink to &quot;Step 1. Open the Captcha Settings&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Spam Protection</strong> → <strong>Captchas</strong>.</li><li>Select <strong>Question</strong> in the left-hand sidebar.</li><li>Turn on <strong>Enabled</strong>.</li></ol><h3 id="step-2-add-your-security-questions" tabindex="-1">Step 2. Add Your Security Questions <a class="header-anchor" href="#step-2-add-your-security-questions" aria-label="Permalink to &quot;Step 2. Add Your Security Questions&quot;">​</a></h3><ol><li>In <strong>Security Questions</strong>, add one or more questions.</li><li>For each question, enter one or more accepted answers in <strong>Answers (comma-separated)</strong>.</li><li>Save the captcha settings.</li></ol><h3 id="step-3-form-setting" tabindex="-1">Step 3. Form Setting <a class="header-anchor" href="#step-3-form-setting" aria-label="Permalink to &quot;Step 3. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to protect.</li><li>Enable <strong>Question</strong> for that form.</li><li>For multi-page forms, turn on <strong>Show on All Pages</strong> if the question should appear on every page instead of only the final submit step.</li><li>Save the form.</li></ol><p>Formie picks one configured question at random. Answer matching is forgiving about case and punctuation, so there is no need to add every capitalization variant.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Submit through the site and check the resulting submission and spam state. A saved credential alone does not verify the visitor-facing challenge or server-side check.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',12)])])}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
